const visual = {
  prepare: function (input) {
    return [{ kind: 'text', payload: '2:3' }];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var y = Math.round(H * 0.58);
    var x0 = Math.round(W * 0.12);
    var x1 = Math.round(W * 0.88);
    var xm = Math.round(x0 + (x1 - x0) * 0.4);
    var seg1 = [['M', x0, y], ['L', xm, y]];
    var seg2 = [['M', xm, y], ['L', x1, y]];
    var ticks = [
      ['M', x0, y - 10], ['L', x0, y + 10],
      ['M', xm, y - 14], ['L', xm, y + 14],
      ['M', x1, y - 10], ['L', x1, y + 10]
    ];
    return {
      schemaVersion: 1,
      sceneId: 'ratio-2-3',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'seg1', commands: seg1 },
        { id: 'seg2', commands: seg2 },
        { id: 'ticks', commands: ticks }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'seg1', fill: '#2f6fb2', stroke: { width: 6, cap: 'round' } },
          { type: 'path', pathId: 'seg2', fill: '#d97706', stroke: { width: 6, cap: 'round' } },
          { type: 'path', pathId: 'ticks', fill: '#26354a', stroke: { width: 2, cap: 'round' } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: Math.round(W / 2), y: y - 34 }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' }
        ]
      }
    };
  }
};
